<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Manajemen Akun</title><style>*{box-sizing:border-box;font-family:Arial}body{margin:0;background:#f3f6fb;color:#344054}nav{background:#123c70;color:white;padding:18px 7%}nav a{color:white}.container{max-width:1100px;margin:35px auto;padding:20px}.panel{background:white;border-radius:12px;padding:22px;overflow:auto}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:13px;border-bottom:1px solid #eee}select,button{padding:9px;border-radius:7px;border:1px solid #ccd}.btn{background:#1766a8;color:white;border:0}.success{background:#dcfce7;padding:12px;margin-bottom:15px}</style></head><body><nav><a href="{{ route('coordinator.dashboard') }}">← Dashboard Koordinator</a></nav><div class="container"><h1>Manajemen Akun</h1><p>Koordinator dapat mengubah role akun. Akun sendiri tidak dapat diubah dari halaman ini.</p>@if(session('success'))<div class="success">{{ session('success') }}</div>@endif @if($errors->any())<div>{{ $errors->first() }}</div>@endif<div class="panel"><table><thead><tr><th>Nama</th><th>Email</th><th>Role saat ini</th><th>Ubah role</th></tr></thead><tbody>@foreach($users as $account)<tr><td>{{ $account->name }}</td><td>{{ $account->email }}</td><td>{{ ucfirst($account->role) }}</td><td>@if(auth()->id() !== $account->id)<form method="POST" action="{{ route('coordinator.users.role',$account) }}">@csrf @method('PATCH')<select name="role"><option value="user" @selected($account->role==='user')>User</option><option value="admin" @selected($account->role==='admin')>Admin</option><option value="coordinator" @selected($account->role==='coordinator')>Koordinator</option></select> <button class="btn">Simpan</button></form>@else Akun aktif @endif</td></tr>@endforeach</tbody></table>{{ $users->links() }}</div></div></body></html>
